// Runs on ALL rows the trigger emits (1 normally; 2+ if multiple forms land
// in one poll window or via Fetch Test Event). Process EVERY item.
const META = new Set([
  'Timestamp', 'Email Address', 'What is your name?',
  'What date, day and time do you need the food/service?',
  'Contact number or mobile (for confirmation & follow-up)',
  'What type of event are you planning?', 'Estimated number of guests attending:',
  'Service Method ', 'Service Method', 'Delivery location ', 'Delivery location',
  '"On which social media platform was the advertisement seen?"',
  'row_number', 'Invoice ID', 'Sync Status',
]);
// Robust metadata test: known META columns, the social-media
// question (curly OR straight quotes), and the policy/terms blob.
const isMeta = (h) => {
  if (META.has(h)) return true;
  const t = String(h).toLowerCase();
  if (t.includes('social media platform')) return true;
  if (t.includes('order, payment') || t.startsWith('bagnetchon order')) return true;
  return false;
};


return $input.all().map((entry) => {
  const row = entry.json;
  const errors = [];

  const email = String(row['Email Address'] ?? '').trim();
  if (!email) errors.push('email is missing');
  else if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) errors.push('email format looks wrong');

  const name = String(row['What is your name?'] ?? '').trim();
  if (!name) errors.push('name is missing');

  const fulfillmentDate = String(row['What date, day and time do you need the food/service?'] ?? '').trim();
  if (!fulfillmentDate) errors.push('fulfillment date is missing');

  const serviceMethod = String(row['Service Method '] ?? row['Service Method'] ?? '').trim();
  if (!serviceMethod) errors.push('service method is missing');

  if (serviceMethod.toLowerCase().includes('delivery')) {
    const deliveryLocation = String(row['Delivery location '] ?? row['Delivery location'] ?? '').trim();
    if (!deliveryLocation) errors.push('delivery location is required for Delivery orders');
  }

  let hasSelection = false;
  for (const [k, v] of Object.entries(row)) {
    if (isMeta(k)) continue;

    if (v && String(v).trim()) { hasSelection = true; break; }
  }
  if (!hasSelection) errors.push('no menu items selected');

  return { json: { ok: errors.length === 0, row, errors } };
});

const crypto = require('crypto');

const META = new Set([
  'Timestamp', 'Email Address', 'What is your name?',
  'What date, day and time do you need the food/service?',
  'Contact number or mobile (for confirmation & follow-up)',
  'What type of event are you planning?', 'Estimated number of guests attending:',
  'Service Method ', 'Service Method', 'Delivery location ', 'Delivery location',
  '"On which social media platform was the advertisement seen?"',
  'row_number', 'Invoice ID', 'Sync Status',
]);
// Robust metadata test: known META columns, the social-media
// question (curly OR straight quotes), and the policy/terms blob.
const isMeta = (h) => {
  if (META.has(h)) return true;
  const t = String(h).toLowerCase();
  if (t.includes('social media platform')) return true;
  if (t.includes('order, payment') || t.startsWith('bagnetchon order')) return true;
  return false;
};


return $input.all().map((entry) => {
  const row = entry.json.row;

  const email = String(row['Email Address'] ?? '').trim().toLowerCase();
  const timestamp = String(row['Timestamp'] ?? '').trim();

  const idHash = crypto.createHash('sha256').update(timestamp + '|' + email).digest('hex').slice(0, 16);

  const selected_items = [];
  for (const [k, v] of Object.entries(row)) {
    if (isMeta(k)) continue;

    if (!v || !String(v).trim()) continue;
    const text = String(v).trim();
    if (k.startsWith('Bagnetchon Signature Menu')) {
      // Multi-select lechon column: comma-separated selections.
      for (const part of text.split(/,\s+/).map((s) => s.trim()).filter(Boolean)) {
        selected_items.push({ sheet_column_header: k, selected_text: part });
      }
    } else {
      selected_items.push({ sheet_column_header: k, selected_text: text });
    }
  }

  const serviceMethod = String(row['Service Method '] ?? row['Service Method'] ?? '').trim();
  const deliveryLocation = String(row['Delivery location '] ?? row['Delivery location'] ?? '').trim();

  return { json: {
    source: 'google_sheet',
    source_row_id: 'gs:' + idHash,
    customer: {
      email,
      name: String(row['What is your name?'] ?? '').trim(),
      phone: String(row['Contact number or mobile (for confirmation & follow-up)'] ?? '').trim(),
    },
    fulfillment: {
      date: String(row['What date, day and time do you need the food/service?'] ?? '').trim(),
      type: serviceMethod,
      address: deliveryLocation || null,
      event_type: String(row['What type of event are you planning?'] ?? '').trim(),
      guest_count: row['Estimated number of guests attending:'] ?? null,
    },
    selected_items,
    writeback: {
      kind: 'google_sheet',
      spreadsheet_id: $vars.GS_SPREADSHEET_ID,
      sheet_name: $vars.GS_RESPONSES_SHEET,
      row_number: row.row_number ?? null,
    },
  }};
});

// Build a notify payload for EACH failed row.
return $input.all().map((entry) => {
  const v = entry.json;
  return { json: {
    severity: 'error',
    stage: 'sheet-intake-validation',
    source: 'google_sheet',
    errors: v.errors || ['unknown validation failure'],
    row: v.row,
  }};
});
